<script>
window.layoutBuilderConfig=@json($builderConfig);
document.addEventListener('DOMContentLoaded',()=>{
 const imageOption=item=>{if(!item.id)return item.text;const url=item.element?.dataset.url,wrapper=document.createElement('span');wrapper.className='select2-image-option';if(url){const image=document.createElement('img');image.src=url;image.alt='';image.loading='lazy';wrapper.appendChild(image)}const label=document.createElement('span');label.textContent=item.text;wrapper.appendChild(label);return wrapper};
 const imageSelect={theme:'bootstrap-5',width:'100%',allowClear:true,templateResult:imageOption,templateSelection:imageOption};
 $('#propLibraryImage').select2({...imageSelect,placeholder:'Pesquise uma imagem'});
 $('#propResponsibleSignature').select2({...imageSelect,placeholder:'Pesquise uma rubrica ou responsável'});
 $('#propTemplateImage').select2({...imageSelect,placeholder:'Pesquise uma imagem do template'});
 const testModal=$('#testModal');
 $('#testParticipant').select2({theme:'bootstrap-5',width:'100%',placeholder:'Pesquise um participante',dropdownParent:testModal});
 $('#testActivity').select2({theme:'bootstrap-5',width:'100%',placeholder:'Pesquise uma atividade',allowClear:true,dropdownParent:testModal});
});
</script>
